1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"sort"
11		"strings"
12	)
13	
14	// Reason constants for clusters that cannot enter a release plan.
15	const (
16		ReasonDisabled          = "集群已停用"
17		ReasonExcludeMatched    = "命中排除条件"
18		ReasonIncludeNotMatched = "未命中包含条件"
19	)
20	
21	// LabelCondition is a set of exact key-value matches; all must match.
22	type LabelCondition map[string]string
23	
24	// Cluster is a candidate target for a release.
25	type Cluster struct {
26		ID       string
27		Disabled bool
28		Tags     map[string]string
29	}
30	
31	// ReleasePlanInput describes an application release to plan offline.
32	type ReleasePlanInput struct {
33		App       string
34		Revision  string
35		Image     string
36		BatchSize int
37		// FirstBatchSize, when positive, caps batch 1 at this many clusters
38		// instead of BatchSize; later batches keep the BatchSize cap. Zero means
39		// unset (batch 1 uses BatchSize like every other batch). It must never
40		// exceed BatchSize.
41		FirstBatchSize int
42		Clusters       []Cluster
43		Include        []LabelCondition
44		Exclude        []LabelCondition
45		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
46		// fault domain; each batch then contains at most one cluster per domain.
47		SpreadBy string
48	}
49	
50	// AppInfo identifies the application being released.
51	type AppInfo struct {
52		Name     string `json:"name"`
53		Revision string `json:"revision"`
54		Image    string `json:"image"`
55	}
56	
57	// Batch is a sequentially numbered group of cluster IDs.
58	type Batch struct {
59		Index    int      `json:"index"`
60		Clusters []string `json:"clusters"`
61	}
62	
63	// ExcludedCluster explains why a cluster is not in the plan.
64	type ExcludedCluster struct {
65		ID     string `json:"id"`
66		Reason string `json:"reason"`
67	}
68	
69	// ReleasePlan is the deterministic offline release plan.
70	type ReleasePlan struct {
71		App      AppInfo           `json:"app"`
72		Batches  []Batch           `json:"batches"`
73		Excluded []ExcludedCluster `json:"excluded"`
74	}
75	
76	// ParseReleaseInput reads a release plan document and validates its fields.
77	// Every string in the document — member names and values, in known fields
78	// and in unknown extra fields — must be legal text: invalid UTF-8 bytes and
79	// \uXXXX escapes naming an unpaired surrogate are rejected first, before any
80	// decoded string can be silently rewritten to "�" and compared. Every JSON
81	// object in the document — including unknown fields and their nested
82	// objects — must then have distinct member names; a name appearing twice
83	// (even with the same value, or via equivalent Unicode escapes) is rejected
84	// before any business validation runs. The document's structural nesting
85	// is capped at maxJSONNestingDepth levels in every field, known or not; a
86	// document that opens a 10001st level is rejected with
87	// errJSONDepthExceeded before any business validation or planning runs.
88	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
89		if err := checkStrictText(data); err != nil {
90			return ReleasePlanInput{}, err
91		}
92		if err := checkDuplicateMembers(data); err != nil {
93			return ReleasePlanInput{}, err
94		}
95		dec := json.NewDecoder(bytes.NewReader(data))
96		dec.UseNumber()
97		var doc map[string]any
98		if err := dec.Decode(&doc); err != nil {
99			if isJSONDepthError(err) {
100				return ReleasePlanInput{}, errJSONDepthExceeded
101			}
102			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
103		}
104		if dec.More() {
105			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
106		}
107		return buildReleaseInput(doc)
108	}
109	
110	// duplicateMemberError reports a JSON object whose member name appears more
111	// than once. Path is a JSONPath-style location that points at the object
112	// owning the duplicate (the duplicate member name itself is reported
113	// separately in field): "$" for the document root, "$.clusters[1]" for a
114	// cluster, "$.clusters[0].tags" for a tag object,
115	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
116	// objects nested inside unknown fields. A member name that is not a plain
117	// identifier is wrapped in brackets around a JSON string, so that characters
118	// in the name can never be read as hierarchy or an array index: a top-level
119	// member "meta.info" is at $["meta.info"] (distinct from the nested object
120	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
121	// that are empty or contain quotes, backslashes or control characters are
122	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
123	type duplicateMemberError struct {
124		field string
125		path  string
126	}
127	
128	func (e *duplicateMemberError) Error() string {
129		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
130	}
131	
132	// checkDuplicateMembers walks every JSON object in data and rejects objects
133	// with duplicate member names. Names are compared after JSON decoding, so
134	// "env" and "env" are the same name while "env" and "ENV", or
135	// " env" and "env", are different. The first duplicate encountered in file
136	// order is reported: the walk is depth-first in document order, so the
137	// second occurrence that appears earliest wins, regardless of value type.
138	//
139	// The check is a policy over the shared structural walk (jsonwalk.go): the
140	// walker recognizes the nesting, decodes the member names and tracks each
141	// object's location; this check only keeps the seen-name set of each object.
142	// A document the walk cannot fully vouch for — an unrecognized structure,
143	// trailing content, or a malformed number the walk stopped on — is handed to
144	// the encoding/json walk, which reports the established format error (and
145	// any duplicate preceding the malformation) with the existing wording.
146	func checkDuplicateMembers(data []byte) error {
147		dup, recognized := scanDuplicateMembers(data)
148		// The nesting limit is a verdict by itself: it holds whether or not the
149		// document is otherwise well-formed and needs no json.Valid confirmation,
150		// so a too-deep document stops here instead of being scanned twice.
151		if errors.Is(dup, errJSONDepthExceeded) {
152			return dup
153		}
154		// json.Valid confirms the whole document — including every number the
155		// walk grammar-checked and any trailing content — is one well-formed
156		// JSON value, so a completed walk's verdict can be trusted directly.
157		// Legal numbers beyond float64 range (e.g. 1e400) are valid JSON and
158		// pass; whether a number is acceptable for a given field is decided
159		// later by business validation.
160		if recognized && json.Valid(data) {
161			return dup
162		}
163		return checkJSONFormatAndDuplicates(data)
164	}
165	
166	// scanDuplicateMembers runs the duplicate-member policy over the shared
167	// structural walk. It reports the first duplicate in file order — the walk
168	// is depth-first in document order, so the second occurrence that appears
169	// earliest wins — and whether the walk recognized the document's structure
170	// (no errUndecided and no text problem, both of which leave the verdict to
171	// the decoder walk). recognized does not by itself mean the document is
172	// well-formed JSON: the caller confirms that with json.Valid.
173	func scanDuplicateMembers(data []byte) (dup error, recognized bool) {
174		// Each entered object's frame id is unique, so the seen-name sets are
175		// keyed by the owning object's id; the walk needs no enter/exit events
176		// for them.
177		seen := make(map[uint64]map[string]struct{})
178		var w *jsonWalker
179		w = &jsonWalker{data: data, onMember: func(ownerID uint64, name string) error {
180			set := seen[ownerID]
181			if set == nil {
182				set = make(map[string]struct{})
183				seen[ownerID] = set
184			}
185			if _, ok := set[name]; ok {
186				dup = &duplicateMemberError{field: name, path: w.framePathByID(ownerID)}
187				return dup
188			}
189			set[name] = struct{}{}
190			return nil
191		}}
192		if err := w.walk(); err != nil && dup == nil {
193			if errors.Is(err, errJSONDepthExceeded) {
194				return err, true
195			}
196			return nil, false
197		}
198		return dup, true
199	}
200	
201	// checkJSONFormatAndDuplicates is the encoding/json walk that documents the
202	// raw structural walk cannot recognize are handed to. It reports the JSON
203	// format error with the established wording — and a duplicate member when
204	// its second occurrence precedes the malformation — exactly as the duplicate
205	// check always has for such documents. The Token API enforces no nesting
206	// limit of its own, so the walk carries the same maxJSONNestingDepth
207	// counter: a malformed document that is also too deep (e.g. one with no
208	// closing brackets at all) is refused with errJSONDepthExceeded instead of
209	// recursing down the reader's call stack and reporting "unclosed" later.
210	func checkJSONFormatAndDuplicates(data []byte) error {
211		dec := json.NewDecoder(bytes.NewReader(data))
212		// Numbers are only walked past, never interpreted: UseNumber keeps legal
213		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
214		// unmarshal-overflow error here. Whether a number is acceptable for a given
215		// field is decided later by business validation.
216		dec.UseNumber()
217		depth := 0
218		if err := walkJSONValue(dec, "$", &depth); err != nil {
219			return err
220		}
221		if _, err := dec.Token(); err != io.EOF {
222			if err == nil {
223				return errors.New("JSON 格式错误: 文档包含多余内容")
224			}
225			if isJSONDepthError(err) {
226				return errJSONDepthExceeded
227			}
228			return fmt.Errorf("JSON 格式错误: %w", err)
229		}
230		return nil
231	}
232	
233	// enterContainer enforces the shared nesting limit on the Token walk: the
234	// root container is level 1 and each entered object or array adds one,
235	// exactly as in the raw walker. It returns errJSONDepthExceeded at the
236	// 10001st level.
237	func enterContainer(depth *int) error {
238		*depth++
239		if *depth > maxJSONNestingDepth {
240			return errJSONDepthExceeded
241		}
242		return nil
243	}
244	
245	// leaveContainer marks one container closed.
246	func leaveContainer(depth *int) {
247		*depth--
248	}
249	
250	// walkJSONValue reads one complete JSON value whose first token has not been
251	// consumed yet. Together with walkJSONObject and walkJSONArray it is the
252	// decoding half of checkJSONFormatAndDuplicates: it only runs for documents
253	// the shared structural walk could not recognize, to report the format error
254	// (or an earlier duplicate) with the established wording.
255	func walkJSONValue(dec *json.Decoder, path string, depth *int) error {
256		tok, err := dec.Token()
257		if err != nil {
258			if err == io.EOF {
259				return errors.New("JSON 格式错误: 文档为空")
260			}
261			if isJSONDepthError(err) {
262				return errJSONDepthExceeded
263			}
264			return fmt.Errorf("JSON 格式错误: %w", err)
265		}
266		return walkJSONValueToken(dec, path, tok, depth)
267	}
268	
269	// walkJSONValueToken reads the remainder of a value given its first token.
270	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token, depth *int) error {
271		if d, ok := tok.(json.Delim); ok {
272			if err := enterContainer(depth); err != nil {
273				return err
274			}
275			switch d {
276			case '{':
277				return walkJSONObject(dec, path, depth)
278			case '[':
279				return walkJSONArray(dec, path, depth)
280			default:
281				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
282			}
283		}
284		return nil // scalar value (string, number, bool, null)
285	}
286	
287	func walkJSONObject(dec *json.Decoder, path string, depth *int) error {
288		defer leaveContainer(depth)
289		seen := make(map[string]struct{})
290		for {
291			tok, err := dec.Token()
292			if err != nil {
293				if err == io.EOF {
294					return errors.New("JSON 格式错误: 对象未闭合")
295				}
296				if isJSONDepthError(err) {
297					return errJSONDepthExceeded
298				}
299				return fmt.Errorf("JSON 格式错误: %w", err)
300			}
301			if d, ok := tok.(json.Delim); ok {
302				if d == '}' {
303					return nil
304				}
305				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
306			}
307			key, ok := tok.(string)
308			if !ok {
309				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
310			}
311			if _, dup := seen[key]; dup {
312				return &duplicateMemberError{field: key, path: path}
313			}
314			seen[key] = struct{}{}
315			vtok, err := dec.Token()
316			if err != nil {
317				if err == io.EOF {
318					return errors.New("JSON 格式错误: 缺少成员值")
319				}
320				if isJSONDepthError(err) {
321					return errJSONDepthExceeded
322				}
323				return fmt.Errorf("JSON 格式错误: %w", err)
324			}
325			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok, depth); err != nil {
326				return err
327			}
328		}
329	}
330	
331	func walkJSONArray(dec *json.Decoder, path string, depth *int) error {
332		defer leaveContainer(depth)
333		for i := 0; ; i++ {
334			tok, err := dec.Token()
335			if err != nil {
336				if err == io.EOF {
337					return errors.New("JSON 格式错误: 数组未闭合")
338				}
339				if isJSONDepthError(err) {
340					return errJSONDepthExceeded
341				}
342				return fmt.Errorf("JSON 格式错误: %w", err)
343			}
344			if d, ok := tok.(json.Delim); ok && d == ']' {
345				return nil
346			}
347			if err := walkJSONValueToken(dec, joinIndexPath(path, i), tok, depth); err != nil {
348				return err
349			}
350		}
351	}
352	
353	// isJSONDepthError reports whether err is encoding/json's own
354	// nesting-limit failure (Decode/Valid enforce it even though the Token
355	// API does not). The message is matched rather than a typed error,
356	// because the scanner's "exceeded max depth" SyntaxError is not exported
357	// as one.
358	func isJSONDepthError(err error) bool {
359		return err != nil && strings.Contains(err.Error(), "exceeded max depth")
360	}
361	
362	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
363		app, err := requiredString(doc, "app")
364		if err != nil {
365			return ReleasePlanInput{}, err
366		}
367		revision, err := requiredString(doc, "revision")
368		if err != nil {
369			return ReleasePlanInput{}, err
370		}
371		image, err := requiredString(doc, "image")
372		if err != nil {
373			return ReleasePlanInput{}, err
374		}
375		batchSize, err := positiveInt(doc, "batchSize")
376		if err != nil {
377			return ReleasePlanInput{}, err
378		}
379		firstBatchSize, err := optionalPositiveInt(doc, "firstBatchSize")
380		if err != nil {
381			return ReleasePlanInput{}, err
382		}
383		if err := checkFirstBatchSize(firstBatchSize, batchSize); err != nil {
384			return ReleasePlanInput{}, err
385		}
386		spreadBy, err := optionalSpreadBy(doc)
387		if err != nil {
388			return ReleasePlanInput{}, err
389		}
390		clusters, err := parseClusters(doc["clusters"])
391		if err != nil {
392			return ReleasePlanInput{}, err
393		}
394		include, err := parseConditions(doc, "include")
395		if err != nil {
396			return ReleasePlanInput{}, err
397		}
398		exclude, err := parseConditions(doc, "exclude")
399		if err != nil {
400			return ReleasePlanInput{}, err
401		}
402	
403		return ReleasePlanInput{
404			App:            app,
405			Revision:       revision,
406			Image:          image,
407			BatchSize:      batchSize,
408			FirstBatchSize: firstBatchSize,
409			Clusters:       clusters,
410			Include:        include,
411			Exclude:        exclude,
412			SpreadBy:       spreadBy,
413		}, nil
414	}
415	
416	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
417	// string disables fault-domain spreading; a non-string value or a string of
418	// only whitespace is rejected. The tag key is used exactly as written.
419	func optionalSpreadBy(doc map[string]any) (string, error) {
420		v, ok := doc["spreadBy"]
421		if !ok {
422			return "", nil
423		}
424		s, ok := v.(string)
425		if !ok {
426			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
427		}
428		if err := checkSpreadBy(s); err != nil {
429			return "", err
430		}
431		return s, nil
432	}
433	
434	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
435	// tag key: a string of only whitespace can never match a valid tag key.
436	func checkSpreadBy(s string) error {
437		if s != "" && strings.TrimSpace(s) == "" {
438			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
439		}
440		return nil
441	}
442	
443	// checkFirstBatchSize applies the firstBatchSize rule shared by the JSON
444	// entry and a directly constructed Go config: zero means "not set" and is
445	// always legal; a set value must be a positive integer no larger than
446	// batchSize. The value is never rounded, truncated or clamped into range —
447	// an illegal one is a configuration error.
448	func checkFirstBatchSize(firstBatchSize, batchSize int) error {
449		if firstBatchSize < 0 {
450			return errors.New(`字段 "firstBatchSize" 必须是正整数`)
451		}
452		if firstBatchSize > batchSize {
453			return errors.New(`字段 "firstBatchSize" 不能大于 "batchSize"`)
454		}
455		return nil
456	}
457	
458	// ValidateReleaseInput checks that a release configuration is well-formed.
459	// Every string is first required to be legal UTF-8 — app, revision, image,
460	// spreadBy, every candidate's ID and tag keys/values (disabled and
461	// filtered-out candidates included), and every include/exclude condition's
462	// keys and values — because invalid bytes would later be rewritten to "�"
463	// while the plan is written as JSON and could merge two distinct identities
464	// or take part in label matching as an ordinary value. That text check runs
465	// before any business rule, in a fixed order (field order, then candidate
466	// and condition positions from zero, then keys in ascending order), so the
467	// one problem it reports never depends on map iteration. Business
468	// validation then runs as before: app/revision/image are non-empty,
469	// batchSize is a positive integer, firstBatchSize is zero (unset) or a
470	// positive integer no larger than batchSize, spreadBy is empty or a usable
471	// tag key
472	// (not whitespace-only), cluster IDs are unique across every candidate
473	// (including disabled and filtered-out clusters), and tag/condition keys
474	// are non-empty. Errors name the field and the position in its list; within
475	// a cluster the ID is checked before its tags, and tag keys are examined in
476	// ascending order so repeated calls report the same error. The input is
477	// never mutated. MakeReleasePlan calls this automatically; library callers
478	// may use it to validate without planning.
479	func ValidateReleaseInput(in ReleasePlanInput) error {
480		if err := validateStrictText(in); err != nil {
481			return err
482		}
483		if strings.TrimSpace(in.App) == "" {
484			return errors.New(`字段 "app" 不能为空或只含空白`)
485		}
486		if strings.TrimSpace(in.Revision) == "" {
487			return errors.New(`字段 "revision" 不能为空或只含空白`)
488		}
489		if strings.TrimSpace(in.Image) == "" {
490			return errors.New(`字段 "image" 不能为空或只含空白`)
491		}
492		if in.BatchSize <= 0 {
493			return errors.New(`字段 "batchSize" 必须是正整数`)
494		}
495		if err := checkFirstBatchSize(in.FirstBatchSize, in.BatchSize); err != nil {
496			return err
497		}
498		if err := checkSpreadBy(in.SpreadBy); err != nil {
499			return err
500		}
501		ids := newClusterIDSet(len(in.Clusters))
502		for i, c := range in.Clusters {
503			if err := ids.check(i, c.ID); err != nil {
504				return err
505			}
506			if err := validateTagKeys(i, c.Tags); err != nil {
507				return err
508			}
509		}
510		if err := validateConditionKeys("include", in.Include); err != nil {
511			return err
512		}
513		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
514			return err
515		}
516		return nil
517	}
518	
519	// validateTagKeys applies the shared label-key rule to one cluster's tags,
520	// reporting the cluster's position in the candidate list.
521	func validateTagKeys(clusterIndex int, tags map[string]string) error {
522		if hasEmptyLabelKey(tags) {
523			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
524		}
525		return nil
526	}
527	
528	// validateConditionKeys applies the shared condition rules to every condition
529	// in original order, so the first invalid condition is reported.
530	func validateConditionKeys(field string, conds []LabelCondition) error {
531		for i, cond := range conds {
532			if err := validateCondition(field, i, cond); err != nil {
533				return err
534			}
535		}
536		return nil
537	}
538	
539	func requiredString(doc map[string]any, field string) (string, error) {
540		v, ok := doc[field]
541		if !ok {
542			return "", fmt.Errorf("缺少必需字段 %q", field)
543		}
544		s, ok := v.(string)
545		if !ok {
546			return "", fmt.Errorf("字段 %q 必须是字符串", field)
547		}
548		if strings.TrimSpace(s) == "" {
549			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
550		}
551		return s, nil
552	}
553	
554	// positiveInt reads a required field as a positive integer. The literal must
555	// be an integral JSON number whose value is representable in full by the Go
556	// int of the running environment: a value beyond math.MaxInt is rejected here
557	// rather than narrowed by an int() conversion, which on a 32-bit environment
558	// could turn 4294967297 into 1 (or a larger value into zero or a negative
559	// number). No truncation, rounding, default substitution or clamping to the
560	// maximum ever happens — such a value is a configuration error regardless of
561	// what int it would collapse into.
562	func positiveInt(doc map[string]any, field string) (int, error) {
563		v, ok := doc[field]
564		if !ok {
565			return 0, fmt.Errorf("缺少必需字段 %q", field)
566		}
567		return positiveIntValue(v, field)
568	}
569	
570	// optionalPositiveInt reads an optional field with exactly the positiveInt
571	// rule; an absent field yields 0 ("not set"). A field that is present must
572	// hold a legal positive integer literal — an explicit zero, a negative
573	// number, a fraction, a non-number or an out-of-range value is rejected, never
574	// ignored or narrowed.
575	func optionalPositiveInt(doc map[string]any, field string) (int, error) {
576		v, ok := doc[field]
577		if !ok {
578			return 0, nil
579		}
580		return positiveIntValue(v, field)
581	}
582	
583	// positiveIntValue validates one decoded JSON value as a positive integer
584	// literal for field, shared by the required and optional field readers.
585	func positiveIntValue(v any, field string) (int, error) {
586		n, ok := v.(json.Number)
587		if !ok {
588			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
589		}
590		i, err := n.Int64()
591		if err != nil || i <= 0 || i > math.MaxInt {
592			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
593		}
594		return int(i), nil
595	}
596	
597	func parseClusters(v any) ([]Cluster, error) {
598		if v == nil {
599			return nil, errors.New("缺少必需字段 \"clusters\"")
600		}
601		raw, ok := v.([]any)
602		if !ok {
603			return nil, errors.New("字段 \"clusters\" 必须是数组")
604		}
605		clusters := make([]Cluster, 0, len(raw))
606		ids := newClusterIDSet(len(raw))
607		for i, item := range raw {
608			obj, ok := item.(map[string]any)
609			if !ok {
610				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
611			}
612			id, err := clusterIDFromJSON(obj, i, ids)
613			if err != nil {
614				return nil, err
615			}
616	
617			disabled := false
618			if dv, present := obj["disabled"]; present {
619				b, ok := dv.(bool)
620				if !ok {
621					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
622				}
623				disabled = b
624			}
625	
626			tags := map[string]string{}
627			if tv, present := obj["tags"]; present {
628				tm, ok := tv.(map[string]any)
629				if !ok {
630					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
631				}
632				tags, err = labelsFromJSON(tm,
633					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
634					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
635				)
636				if err != nil {
637					return nil, err
638				}
639			}
640	
641			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
642		}
643		return clusters, nil
644	}
645	
646	// clusterIDFromJSON reads the "id" member of one candidate object and applies
647	// the shared cluster-identity rule. A missing member or a non-string value is
648	// a JSON decoding problem with its own reason; an empty or duplicate ID is
649	// reported by the shared rule exactly as for a directly constructed config.
650	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
651		v, ok := obj["id"]
652		if !ok {
653			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
654		}
655		id, ok := v.(string)
656		if !ok {
657			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
658		}
659		if err := ids.check(index, id); err != nil {
660			return "", err
661		}
662		return id, nil
663	}
664	
665	// parseConditions reads the optional include/exclude field from the decoded
666	// document. An absent field means "no conditions" (the same as an explicit
667	// empty array); a field that is present must be an array of condition
668	// objects. An explicit JSON null is a field type error — it must not be read
669	// as "no conditions", which would silently drop the filter the author wrote.
670	func parseConditions(doc map[string]any, field string) ([]LabelCondition, error) {
671		v, ok := doc[field]
672		if !ok {
673			return []LabelCondition{}, nil
674		}
675		raw, ok := v.([]any)
676		if !ok {
677			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
678		}
679		conds := make([]LabelCondition, 0, len(raw))
680		for i, item := range raw {
681			obj, ok := item.(map[string]any)
682			if !ok {
683				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
684			}
685			cond, err := labelsFromJSON(obj,
686				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
687				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
688			)
689			if err != nil {
690				return nil, err
691			}
692			if err := validateCondition(field, i, cond); err != nil {
693				return nil, err
694			}
695			conds = append(conds, cond)
696		}
697		return conds, nil
698	}
699	
700	// MakeReleasePlan selects available clusters, orders them by ID, and splits
701	// them into batches. When SpreadBy names a tag, each batch holds at most one
702	// cluster per value of that tag (its fault domain) and every selected cluster
703	// must carry the tag. When FirstBatchSize is set, batch 1 is capped at that
704	// many clusters and every later batch at BatchSize; the first-batch cap is
705	// only a cap — a batch may close short when clusters run out or fault domains
706	// conflict, and no empty batch is ever emitted. It validates the input first
707	// and never mutates it.
708	//
709	// When every candidate is filtered out, the returned error lists each
710	// candidate's rejection reason on its own line, ascending by the original
711	// ID. An ID containing a double quote, backslash, control character or
712	// U+2028/U+2029 is displayed as a quoted JSON string with those characters
713	// escaped (see rejectreport.go), so one candidate always occupies exactly
714	// one line and the original ID can be recovered from the display; this is
715	// only a display spelling — the ID itself is never altered or re-compared.
716	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
717		if err := ValidateReleaseInput(in); err != nil {
718			return ReleasePlan{}, err
719		}
720		if len(in.Clusters) == 0 {
721			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
722		}
723	
724		selected := []string{}
725		excluded := []ExcludedCluster{}
726		for _, c := range in.Clusters {
727			switch {
728			case c.Disabled:
729				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
730			case matchesAny(c.Tags, in.Exclude):
731				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
732			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
733				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
734			default:
735				selected = append(selected, c.ID)
736			}
737		}
738	
739		sort.Strings(selected)
740		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
741	
742		if len(selected) == 0 {
743			var b strings.Builder
744			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
745			for _, e := range excluded {
746				b.WriteString("\n  ")
747				b.WriteString(reportClusterID(e.ID))
748				b.WriteString("：")
749				b.WriteString(e.Reason)
750			}
751			return ReleasePlan{}, errors.New(b.String())
752		}
753	
754		var batches []Batch
755		firstCap := in.BatchSize
756		if in.FirstBatchSize > 0 {
757			firstCap = in.FirstBatchSize
758		}
759		if in.SpreadBy == "" {
760			batches = chunkBatches(selected, in.BatchSize, firstCap)
761		} else {
762			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
763			if err != nil {
764				return ReleasePlan{}, err
765			}
766			batches = spreadBatches(selected, domains, in.BatchSize, firstCap)
767		}
768	
769		return ReleasePlan{
770			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
771			Batches:  batches,
772			Excluded: excluded,
773		}, nil
774	}
775	
776	// chunkBatches splits the ascending IDs into batches of at most batchSize,
777	// except batch 1 which is capped at firstBatchSize instead (callers pass
778	// batchSize when no separate first-batch cap is set). Each batch's Clusters
779	// gets its own backing array: a subslice of selected would leave spare
780	// capacity pointing at the next batch's IDs, so a caller appending to one
781	// batch's list would overwrite the following batch.
782	func chunkBatches(selected []string, batchSize, firstBatchSize int) []Batch {
783		batches := []Batch{}
784		for i := 0; i < len(selected); {
785			size := batchSize
786			if len(batches) == 0 {
787				size = firstBatchSize
788			}
789			end := i + size
790			if end > len(selected) {
791				end = len(selected)
792			}
793			clusters := make([]string, end-i)
794			copy(clusters, selected[i:end])
795			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: clusters})
796			i = end
797		}
798		return batches
799	}
800	
801	// faultDomains maps every selected cluster ID to the exact value of its
802	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
803	// selected is ascending, so the smallest such ID is reported. An empty
804	// string tag value is a valid fault domain, distinct from a missing tag.
805	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
806		tagsByID := make(map[string]map[string]string, len(clusters))
807		for _, c := range clusters {
808			tagsByID[c.ID] = c.Tags
809		}
810		domains := make(map[string]string, len(selected))
811		for _, id := range selected {
812			v, ok := tagsByID[id][spreadBy]
813			if !ok {
814				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
815			}
816			domains[id] = v
817		}
818		return domains, nil
819	}
820	
821	// spreadBatches packs the ascending IDs into batches of at most batchSize
822	// with at most one cluster per fault domain in each batch — except batch 1,
823	// whose capacity is firstBatchSize (callers pass batchSize when no separate
824	// first-batch cap is set). Each batch takes the smallest still-unscheduled
825	// IDs whose domains do not conflict with the batch; conflicting clusters are
826	// deferred to later batches, so a batch may be short only when no
827	// non-conflicting cluster remains. Every ID appears in exactly one batch and
828	// IDs stay ascending within a batch.
829	func spreadBatches(selected []string, domains map[string]string, batchSize, firstBatchSize int) []Batch {
830		remaining := append([]string(nil), selected...)
831		batches := []Batch{}
832		for len(remaining) > 0 {
833			capacity := batchSize
834			if len(batches) == 0 {
835				capacity = firstBatchSize
836			}
837			// The map never holds more entries than there are remaining clusters,
838			// so size it by them — never by the capacity, which is only an upper
839			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
840			used := make(map[string]struct{}, min(capacity, len(remaining)))
841			batch := []string{}
842			deferred := []string{}
843			for _, id := range remaining {
844				d := domains[id]
845				if _, conflict := used[d]; len(batch) < capacity && !conflict {
846					used[d] = struct{}{}
847					batch = append(batch, id)
848				} else {
849					deferred = append(deferred, id)
850				}
851			}
852			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
853			remaining = deferred
854		}
855		return batches
856	}
857	
858	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
859		for _, cond := range conditions {
860			if matchesAll(tags, cond) {
861				return true
862			}
863		}
864		return false
865	}
866	
867	func matchesAll(tags map[string]string, cond LabelCondition) bool {
868		for k, v := range cond {
869			tv, ok := tags[k]
870			if !ok || tv != v {
871				return false
872			}
873		}
874		return true
875	}
876

