10	// This file covers the optional firstBatchSize setting: batch 1 is capped at
11	// firstBatchSize while every later batch keeps the batchSize cap. The setting
12	// is only a cap — selection (disabled/include/exclude) is decided exactly as
13	// before, fault-domain spreading still defers conflicting clusters, every
14	// selected cluster appears in exactly one batch, and no empty batch is ever
15	// emitted. Omitting the field or setting it equal to batchSize must reproduce
16	// the original plan byte-for-byte.
17	
18	// firstBatchDoc builds a plan document with the given batch capacity and
19	// cluster list; first is substituted as a raw JSON literal (use "" to omit
20	// the field entirely).
21	func firstBatchDoc(batchSize int, first string, clusters string) string {
22		doc := `{"app":"app","revision":"r1","image":"img","batchSize":` +
23			strconv.Itoa(batchSize)
24		if first != "" {
25			doc += `,"firstBatchSize":` + first
26		}
27		return doc + `,"clusters":[` + clusters + `]}`
