30	// TestPlan_FirstBatchSpreadByThenFullCapacity is the contract example: a
31	// smaller first batch under fault-domain spreading, with later batches back
32	// at the full batchSize capacity. a,b are east; c,e west; d north. Batch 1 is
33	// capped at 2: a takes east, b conflicts and is deferred, c (west) still
34	// joins. Batch 2 runs at capacity 3 again — b, d and e all fit — proving the
35	// first-batch cap does not stick to later batches.
36	func TestPlan_FirstBatchSpreadByThenFullCapacity(t *testing.T) {
37		in := parsePlan(t, `{
38			"app": "app", "revision": "r1", "image": "img",
39			"batchSize": 3, "firstBatchSize": 2, "spreadBy": "zone",
40			"clusters": [
41				{"id": "a", "tags": {"zone": "east"}},
42				{"id": "b", "tags": {"zone": "east"}},
43				{"id": "c", "tags": {"zone": "west"}},
44				{"id": "d", "tags": {"zone": "north"}},
45				{"id": "e", "tags": {"zone": "west"}}
46			]
47		}`)
48		plan, err := MakeReleasePlan(in)
49		if err != nil {
50			t.Fatal(err)
51		}
52		if got := batchIDs(plan); strings.Join(got, "|") != "a,c|b,d,e" {
53			t.Fatalf("batches = %v, want [a c]|[b d e]", got)
54		}
55		for i, b := range plan.Batches {
56			if b.Index != i+1 {
57				t.Fatalf("batch %d has index %d, want %d", i, b.Index, i+1)
58			}
59		}
60		// Every selected cluster appears exactly once across the plan.
61		seen := map[string]int{}
62		for _, b := range plan.Batches {
63			for _, id := range b.Clusters {
64				seen[id]++
65			}
66		}
67		for _, id := range []string{"a", "b", "c", "d", "e"} {
68			if seen[id] != 1 {
69				t.Fatalf("cluster %q appears %d times, want exactly 1", id, seen[id])
70			}
71		}
72	}
