74	// TestPlan_FirstBatchPlainChunking covers ordinary batching without spreadBy:
75	// batch 1 closes at the first-batch cap, batch 2 regains the full batchSize
76	// capacity, and the tail batch closes short.
77	func TestPlan_FirstBatchPlainChunking(t *testing.T) {
78		in := parsePlan(t, firstBatchDoc(3, "2",
79			`{"id":"c1"},{"id":"c2"},{"id":"c3"},{"id":"c4"},{"id":"c5"},{"id":"c6"},{"id":"c7"}`))
80		plan, err := MakeReleasePlan(in)
