82			t.Fatal(err)
83		}
84		if got := batchIDs(plan); strings.Join(got, "|") != "c1,c2|c3,c4,c5|c6,c7" {
85			t.Fatalf("batches = %v, want [c1 c2]|[c3 c4 c5]|[c6 c7]", got)
86		}
87	}
88	
89	// TestPlan_FirstBatchUnsetOrEqualMatchesOriginal requires three spellings of
90	// "no separate first batch" — field absent, Go zero value, and an explicit
91	// value equal to batchSize — to produce exactly the original plan: same batch
92	// numbering, same cluster order, same excluded list with reasons.
93	func TestPlan_FirstBatchUnsetOrEqualMatchesOriginal(t *testing.T) {
94		clusters := `{"id":"c1"},{"id":"c2","disabled":true},{"id":"c3"},{"id":"c4"},{"id":"c5"}`
95		base := parsePlan(t, firstBatchDoc(2, "", clusters))
96		equal := parsePlan(t, firstBatchDoc(2, "2", clusters))
97		if equal.FirstBatchSize != 2 {
98			t.Fatalf("parsed firstBatchSize = %d, want 2", equal.FirstBatchSize)
99		}
100		if base.FirstBatchSize != 0 {
101			t.Fatalf("absent firstBatchSize must parse as 0 (unset), got %d", base.FirstBatchSize)
102		}
103	
104		planBase, err := MakeReleasePlan(base)
105		if err != nil {
106			t.Fatal(err)
107		}
108		planEqual, err := MakeReleasePlan(equal)
109		if err != nil {
110			t.Fatal(err)
111		}
112		if !reflect.DeepEqual(planBase, planEqual) {
113			t.Fatalf("firstBatchSize == batchSize changed the plan:\n base:  %+v\n equal: %+v", planBase, planEqual)
114		}
115	
116		// The Go zero value (unset) must agree with both.
117		goIn := base
118		goIn.FirstBatchSize = 0
119		planGo, err := MakeReleasePlan(goIn)
120		if err != nil {
121			t.Fatal(err)
122		}
123		if !reflect.DeepEqual(planBase, planGo) {
124			t.Fatalf("Go zero firstBatchSize changed the plan:\n base: %+v\n go:   %+v", planBase, planGo)
125		}
