127		if got := batchIDs(planBase); strings.Join(got, "|") != "c1,c3|c4,c5" {
128			t.Fatalf("original batching changed: %v", got)
129		}
130		if len(planBase.Excluded) != 1 ||
131			planBase.Excluded[0] != (ExcludedCluster{ID: "c2", Reason: ReasonDisabled}) {
132			t.Fatalf("excluded = %+v, want c2: %s", planBase.Excluded, ReasonDisabled)
133		}
134	}
135	
136	// TestPlan_FirstBatchSingleCluster: one selected cluster yields exactly one
137	// batch, however the caps are set.
138	func TestPlan_FirstBatchSingleCluster(t *testing.T) {
139		in := parsePlan(t, firstBatchDoc(3, "2", `{"id":"only"}`))
140		plan, err := MakeReleasePlan(in)
141		if err != nil {
142			t.Fatal(err)
143		}
144		if len(plan.Batches) != 1 || strings.Join(plan.Batches[0].Clusters, ",") != "only" {
145			t.Fatalf("expected one batch [only], got %+v", plan.Batches)
146		}
147		if plan.Batches[0].Index != 1 {
148			t.Fatalf("batch index = %d, want 1", plan.Batches[0].Index)
149		}
150	}
151	
152	// TestPlan_FirstBatchCapIsOnlyAnUpperBound: the first batch may close short —
153	// when fewer clusters are selected than the cap allows, and when fault-domain
154	// conflicts leave no cluster that can still enter it. No empty batch is ever
155	// emitted in either case.
156	func TestPlan_FirstBatchCapIsOnlyAnUpperBound(t *testing.T) {
157		// Fewer selected clusters than the first-batch cap: one short batch only.
158		in := parsePlan(t, firstBatchDoc(3, "2", `{"id":"c1"}`))
159		plan, err := MakeReleasePlan(in)
160		if err != nil {
161			t.Fatal(err)
162		}
163		if len(plan.Batches) != 1 || len(plan.Batches[0].Clusters) != 1 {
164			t.Fatalf("short selection must close batch 1 short without empty batches, got %+v", plan.Batches)
165		}
166	
167		// Domain conflicts: batch 1 (cap 2) takes a(east) and c(west); b and d
168		// conflict and are deferred. Batch 2 at capacity 3 takes b(east) and
169		// d(north) — e(west) conflicts with nothing left but still fits. The
170		// domain limit is never relaxed to fill a batch.
171		in = parsePlan(t, `{
172			"app": "app", "revision": "r1", "image": "img",
173			"batchSize": 3, "firstBatchSize": 2, "spreadBy": "zone",
174			"clusters": [
175				{"id": "a", "tags": {"zone": "east"}},
176				{"id": "b", "tags": {"zone": "east"}},
177				{"id": "c", "tags": {"zone": "west"}}
178			]
179		}`)
180		plan, err = MakeReleasePlan(in)
181		if err != nil {
182			t.Fatal(err)
183		}
184		if got := batchIDs(plan); strings.Join(got, "|") != "a,c|b" {
185			t.Fatalf("batches = %v, want [a c]|[b] (domain limit never relaxed)", got)
186		}
187		for _, b := range plan.Batches {
188			if len(b.Clusters) == 0 {
189				t.Fatalf("plan contains an empty batch: %+v", plan.Batches)
190			}
191		}
192	}
193	
194	// TestPlan_FirstBatchDoesNotChangeSelection: disabled/include/exclude decide
195	// the selected set exactly as without the setting; the first-batch cap only
196	// splits that set differently.
197	func TestPlan_FirstBatchDoesNotChangeSelection(t *testing.T) {
198		in := parsePlan(t, `{
199			"app": "app", "revision": "r1", "image": "img",
200			"batchSize": 3, "firstBatchSize": 1,
201			"include": [{"env": "prod"}],
202			"exclude": [{"quarantine": "true"}],
203			"clusters": [
204				{"id": "c1", "tags": {"env": "prod"}},
205				{"id": "c2", "tags": {"env": "prod", "quarantine": "true"}},
206				{"id": "c3", "disabled": true, "tags": {"env": "prod"}},
207				{"id": "c4", "tags": {"env": "dev"}},
208				{"id": "c5", "tags": {"env": "prod"}}
209			]
210		}`)
211		plan, err := MakeReleasePlan(in)
212		if err != nil {
213			t.Fatal(err)
214		}
215		if got := batchIDs(plan); strings.Join(got, "|") != "c1|c5" {
216			t.Fatalf("batches = %v, want [c1]|[c5]", got)
217		}
218		wantExcluded := []ExcludedCluster{
219			{ID: "c2", Reason: ReasonExcludeMatched},
220			{ID: "c3", Reason: ReasonDisabled},
221			{ID: "c4", Reason: ReasonIncludeNotMatched},
222		}
223		if !reflect.DeepEqual(plan.Excluded, wantExcluded) {
224			t.Fatalf("excluded = %+v, want %+v", plan.Excluded, wantExcluded)
225		}
226	}
227	
228	// TestParse_FirstBatchSizeInvalid: every illegal JSON value for the optional
229	// field is rejected with an error naming the field and the reason — never
230	// ignored, rounded, truncated or clamped — and the returned config is the
231	// zero value. An explicit zero is rejected just like any non-positive value.
232	func TestParse_FirstBatchSizeInvalid(t *testing.T) {
233		clusters := `{"id":"c1"}`
234		cases := map[string]struct {
235			literal string
236			wantErr string
237		}{
238			"explicit zero":     {"0", `字段 "firstBatchSize" 必须是正整数`},
239			"negative":          {"-2", `字段 "firstBatchSize" 必须是正整数`},
240			"fraction":          {"2.5", `字段 "firstBatchSize" 必须是正整数`},
241			"string":            {`"2"`, `字段 "firstBatchSize" 必须是正整数`},
242			"boolean":           {"true", `字段 "firstBatchSize" 必须是正整数`},
243			"null":              {"null", `字段 "firstBatchSize" 必须是正整数`},
244			"overflow":          {"9223372036854775808", `字段 "firstBatchSize" 必须是正整数`},
245			"larger than batch": {"3", `字段 "firstBatchSize" 不能大于 "batchSize"`},
246		}
247		for name, tc := range cases {
248			t.Run(name, func(t *testing.T) {
249				in, err := ParseReleaseInput([]byte(firstBatchDoc(2, tc.literal, clusters)))
250				if err == nil {
251					t.Fatalf("firstBatchSize %s must be rejected, got %+v", tc.literal, in)
252				}
253				if err.Error() != tc.wantErr {
254					t.Fatalf("error = %q, want %q", err.Error(), tc.wantErr)
255				}
256				if !reflect.DeepEqual(in, ReleasePlanInput{}) {
257					t.Fatalf("rejected parse must return the zero-value config, got %+v", in)
258				}
259			})
260		}
261	}
262	
263	// TestValidate_FirstBatchSizeGoConfig: a directly constructed Go config uses
264	// the zero value as "unset"; every other illegal value is rejected before
265	// planning by both ValidateReleaseInput and MakeReleasePlan, the latter
266	// returning the zero-value plan.
267	func TestValidate_FirstBatchSizeGoConfig(t *testing.T) {
268		valid := ReleasePlanInput{
269			App: "app", Revision: "r1", Image: "img", BatchSize: 2,
270			Clusters: []Cluster{{ID: "c1"}, {ID: "c2"}, {ID: "c3"}},
271		}
272	
273		// Zero means unset and plans with the original batching.
274		plan, err := MakeReleasePlan(valid)
275		if err != nil {
276			t.Fatalf("zero firstBatchSize must be legal (unset): %v", err)
277		}
278		if got := batchIDs(plan); strings.Join(got, "|") != "c1,c2|c3" {
279			t.Fatalf("batches = %v, want [c1 c2]|[c3]", got)
280		}
281	
282		cases := map[string]struct {
283			first   int
284			wantErr string
285		}{
286			"negative":          {-1, `字段 "firstBatchSize" 必须是正整数`},
287			"larger than batch": {3, `字段 "firstBatchSize" 不能大于 "batchSize"`},
288		}
289		for name, tc := range cases {
290			t.Run(name, func(t *testing.T) {
291				in := valid
292				in.FirstBatchSize = tc.first
293				if verr := ValidateReleaseInput(in); verr == nil || verr.Error() != tc.wantErr {
294					t.Fatalf("ValidateReleaseInput = %v, want %q", verr, tc.wantErr)
295				}
296				plan, perr := MakeReleasePlan(in)
297				if perr == nil || perr.Error() != tc.wantErr {
298					t.Fatalf("MakeReleasePlan err = %v, want %q", perr, tc.wantErr)
299				}
300				assertZeroReleasePlan(t, plan)
301			})
302		}
303	}
304	
305	// TestPlan_FirstBatchKeepsExistingFailures: the first-batch cap never masks
306	// the established planning failures — all candidates filtered out still
307	// reports every candidate's reason, and a selected cluster missing the
308	// spreadBy tag still fails the whole plan with the zero-value plan.
309	func TestPlan_FirstBatchKeepsExistingFailures(t *testing.T) {
310		allRejected := parsePlan(t, `{
311			"app": "app", "revision": "r1", "image": "img",
312			"batchSize": 3, "firstBatchSize": 1,
313			"include": [{"env": "staging"}],
314			"clusters": [{"id": "b"}, {"id": "a", "disabled": true}]
315		}`)
316		plan, err := MakeReleasePlan(allRejected)
317		if err == nil {
318			t.Fatal("all candidates filtered out must still fail")
319		}
320		assertZeroReleasePlan(t, plan)
321		want := allRejectedLibraryError("a："+ReasonDisabled, "b："+ReasonIncludeNotMatched)
322		if err.Error() != want {
