73	func runDemo() {
74		subjects := []darksafe.Subject{
75			{ID: "u-1001", Kind: "user", Roles: []string{"org/payments/ledger:read"}},
76			{ID: "svc-batch", Kind: "service", Roles: []string{"owner"}},
77			{ID: "u-1002", Kind: "user", Disabled: true},
78		}
79		resource := darksafe.Resource{ID: "ledger-main", Scope: "org/payments/ledger"}
80		allowed := 0
81		for _, subject := range subjects {
82			decision := darksafe.Access(subject, resource, "read")
83			if decision.Allowed {
84				allowed++
85			}
86			fmt.Printf("subject=%s allowed=%v reason=%s\n", subject.ID, decision.Allowed, decision.Reason)
87		}
88		fmt.Printf("summary: %d of %d subjects allowed\n", allowed, len(subjects))
89	}
